param(
    [int]$VersionCode = 101,
    [string]$VersionName = "1.1-hibreak"
)

$ErrorActionPreference = 'Stop'
$here = $PSScriptRoot
$BT = 'C:\Users\abhif\AppData\Local\Android\Sdk\build-tools\36.1.0'
$AJ = 'C:\Users\abhif\AppData\Local\Android\Sdk\platforms\android-36\android.jar'
$Build = Join-Path $here 'build'
Remove-Item -Recurse -Force $Build -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path "$Build/gen/org/b1051c/einkui", "$Build/stubs", "$Build/classes", "$Build/dex" | Out-Null

$gen = @"
package org.b1051c.einkui;

/** Generated by build-win.ps1. */
final class Build {
    static final int CODE = $VersionCode;
    static final String NAME = "$VersionName";
    private Build() {}
}
"@
Set-Content -Path "$Build/gen/org/b1051c/einkui/Build.java" -Value $gen -Encoding UTF8

& "$BT/aapt2.exe" compile --dir (Join-Path $here 'res') -o "$Build/res.zip"
if ($LASTEXITCODE -ne 0) { throw 'aapt2 compile failed' }
$assets = @()
if (Test-Path (Join-Path $here 'assets')) { $assets = @('-A', (Join-Path $here 'assets')) }
& "$BT/aapt2.exe" link -o "$Build/base.apk" -I $AJ --manifest (Join-Path $here 'AndroidManifest.xml') --java "$Build/gen" "$Build/res.zip" @assets --min-sdk-version 31 --target-sdk-version 35 --version-code $VersionCode --version-name $VersionName
if ($LASTEXITCODE -ne 0) { throw 'aapt2 link failed' }

$stubs = Get-ChildItem (Join-Path $here 'stubs') -Recurse -Filter '*.java' | ForEach-Object FullName
& javac -Xlint:-options -source 17 -target 17 -encoding UTF-8 -classpath $AJ -d "$Build/stubs" $stubs
if ($LASTEXITCODE -ne 0) { throw 'stub javac failed' }
$sources = @((Get-ChildItem (Join-Path $here 'src') -Recurse -Filter '*.java' | ForEach-Object FullName)) + @((Get-ChildItem "$Build/gen" -Recurse -Filter '*.java' | ForEach-Object FullName))
& javac -Xlint:-options -source 17 -target 17 -encoding UTF-8 -classpath "$AJ;$Build/stubs" -d "$Build/classes" $sources
if ($LASTEXITCODE -ne 0) { throw 'javac failed' }

$classes = Get-ChildItem "$Build/classes" -Recurse -Filter '*.class' | ForEach-Object FullName
& "$BT/d8.bat" --lib $AJ --classpath "$Build/stubs" --min-api 31 --release --output "$Build/dex" $classes
if ($LASTEXITCODE -ne 0) { throw 'd8 failed' }
Copy-Item -Force "$Build/base.apk" "$Build/unsigned.apk"
& jar uf "$Build/unsigned.apk" -C "$Build/dex" classes.dex
if ($LASTEXITCODE -ne 0) { throw 'jar update failed' }
& "$BT/zipalign.exe" -f -p 4 "$Build/unsigned.apk" "$Build/aligned.apk"
if ($LASTEXITCODE -ne 0) { throw 'zipalign failed' }
& "$BT/apksigner.bat" sign --key (Join-Path $here 'keys/platform.pk8') --cert (Join-Path $here 'keys/platform.x509.pem') --out "$Build/einkui.apk" "$Build/aligned.apk"
if ($LASTEXITCODE -ne 0) { throw 'sign failed' }
& "$BT/apksigner.bat" verify --print-certs "$Build/einkui.apk" | Select-String 'SHA-256'
Get-FileHash -Algorithm SHA256 "$Build/einkui.apk" | Format-List Path,Hash
